#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Production Google OAuth (issue #91). No secret ever passes through this script.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Values captured here are non-secret and live outside the repo, never committed.
ENV_FILE="${ENV_FILE:-$HOME/.config/postszn-wizards/google-oauth.env}"
mkdir -p "$(dirname "$ENV_FILE")"

TOTAL_STAGES=8

banner "Production Google OAuth for PostSzn Fantasy (#91)"

stage "Collect production details"
say "Have these ready: your production domain and your PRODUCTION Supabase project."
note "Use a separate Supabase project from dev. Do not reuse dev keys."
ask PROD_DOMAIN "Production domain, no scheme (e.g. postszn.example.com):"
ask SUPABASE_PROD_REF "Prod Supabase project ref (the 'abc123' in abc123.supabase.co):"
ask SUPPORT_EMAIL "Support/developer contact email for the consent screen:"
write_env PROD_DOMAIN "$PROD_DOMAIN"
write_env SUPABASE_PROD_REF "$SUPABASE_PROD_REF"
write_env SUPPORT_EMAIL "$SUPPORT_EMAIL"
note "Redirect URI to use later: https://${SUPABASE_PROD_REF}.supabase.co/auth/v1/callback"

stage "Google Cloud: create the prod project"
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: 'PostSzn Fantasy Prod' (anything you will recognise)."
step "Pick the Google account that should OWN this long term (not a throwaway)."
step "Click Create, then make sure the project selector at the top shows it."
pause "Project created and selected? Press Enter"

stage "Consent screen: branding"
say "Verification can take days, so do this stage carefully and early."
open_url "https://console.cloud.google.com/auth/branding"
step "If asked to 'Get started': app name 'PostSzn Fantasy', user support email ${SUPPORT_EMAIL}."
step "Audience: choose External."
step "Contact info: ${SUPPORT_EMAIL}. Accept the policy, Create."
step "On Branding, set app logo (optional but helps verification)."
step "Application home page: https://${PROD_DOMAIN}"
step "Privacy policy and Terms of service links: URLs on https://${PROD_DOMAIN}."
warn "Those pages must exist and be reachable on your domain before verification."
step "Authorized domains: add ${PROD_DOMAIN} (or its registrable parent domain)."
step "Click Save."
pause "Branding saved? Press Enter"

stage "Consent screen: scopes (keep them minimal)"
open_url "https://console.cloud.google.com/auth/scopes"
step "Click 'Add or remove scopes' and select ONLY: openid, .../auth/userinfo.email, .../auth/userinfo.profile."
step "Update, then Save."
note "These are non-sensitive scopes, which keeps verification light. Add nothing else."
pause "Scopes saved? Press Enter"

stage "Publish to production"
open_url "https://console.cloud.google.com/auth/audience"
step "Publishing status is 'Testing' by default, which limits sign-in to listed test users"
step "and expires tokens after 7 days. Click 'Publish app' and confirm."
step "Then open the Verification Center and note any requested items:"
open_url "https://console.cloud.google.com/auth/verification"
note "Branding verification (name/logo/domain ownership) may email you; domain ownership"
note "is proven via Google Search Console. Watch the support email's inbox."
confirm "Is the status now 'In production'?" || warn "Come back and publish before launch."
pause "Press Enter to continue"

stage "Create the OAuth client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: 'PostSzn Prod Web'."
step "Authorized JavaScript origins: https://${PROD_DOMAIN}"
step "Authorized redirect URIs: https://${SUPABASE_PROD_REF}.supabase.co/auth/v1/callback"
step "Click Create. Google shows the Client ID and Client secret."
warn "Keep that dialog/tab open. Do NOT paste the secret into this terminal or any file."
ask GOOGLE_CLIENT_ID "Paste the Client ID (public, ends .apps.googleusercontent.com):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"

stage "Supabase prod: enable the Google provider"
say "Paste the Client ID and secret directly into the Supabase dashboard, not here."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/auth/providers"
step "Authentication > Sign In / Providers > Google: toggle Enable."
step "Client IDs: paste the Client ID. Client Secret: paste from the open Google dialog."
step "Save."
pause "Provider saved? Press Enter"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/auth/url-configuration"
step "Site URL: https://${PROD_DOMAIN}"
step "Redirect URLs: add https://${PROD_DOMAIN}/** (the app redirects back to the current page)."
step "Save."
pause "URL configuration saved? Press Enter"
note "Prod frontend env (Vercel/host settings, not this repo): VITE_SUPABASE_URL=https://${SUPABASE_PROD_REF}.supabase.co and the prod publishable key."

stage "Verify end to end"
open_url "https://${PROD_DOMAIN}"
step "Sign in with Google using an account that is NOT a project owner."
step "You should land back on the app, signed in, with no 'unverified app' or"
step "'redirect_uri_mismatch' error. Sign out and repeat in a private window."
if confirm "Did sign-in work?"; then
  say "Done once the consent screen verification (if requested) is approved."
else
  warn "redirect_uri_mismatch: recheck the redirect URI in stage 6 character by character."
  warn "Access blocked / unverified: check the Verification Center in stage 5."
fi
SKIPPED+=("Tick #91 only after sign-in works AND Google verification (if requested) is approved")

finish
}

run_wizard "$@"; exit
